using System.Numerics;
using Gubbins.Span;

namespace Gubbins.Entities.Tests;

/// <summary>
/// Exercises the code generated by <see cref="SpanAsAttribute"/> / <see cref="SpanToAttribute"/>: the attribute turns
/// a component wrapper into a span operation surface over the underlying value type.
/// </summary>
/// <remarks>
/// The components must be <c>partial</c>: the generator nests the operation adapter inside the component and
/// registers it from the component's static constructor.
/// </remarks>
[TestFixture]
public partial class SpanOperationTests
{
    /// <summary>A single-field wrapper; the generated code reinterprets <c>Span&lt;SpeedBox&gt;</c> as <c>Span&lt;float&gt;</c>.</summary>
    /// <remarks>Must be public: the generated extension class is public, so its parameter types must be at least as accessible.</remarks>
    [SpanAs(typeof(ISpanNumberOperation<float>))]
    public partial struct SpeedBox
    {
        public float Value;
    }

    [SpanAs(typeof(ISpanNumberOperation<int>), Member = "Value", Method = "Add", Overwrite = "AddValue")]
    public partial struct ScoreBox
    {
        public int Value;
    }

    private static SpeedBox[] CreateSpeeds(int count)
    {
        var values = new SpeedBox[count];
        for (var i = 0; i < count; i++)
        {
            values[i].Value = i;
        }

        return values;
    }

    [Test]
    public void GeneratedExtension_Add_UpdatesEveryElement()
    {
        var values = CreateSpeeds(16);
        var operand = new SpeedBox { Value = 10f };
        values.AsSpan().Add(operand, values.AsSpan());
        for (var i = 0; i < values.Length; i++)
        {
            Assert.That(values[i].Value, Is.EqualTo(i + 10f));
        }
    }

    [Test]
    public void GeneratedExtension_ScalarOverload_IsGenerated()
    {
        var values = CreateSpeeds(8);
        values.AsSpan().Add(2.5f, values.AsSpan());
        Assert.That(values[0].Value, Is.EqualTo(2.5f));
        Assert.That(values[7].Value, Is.EqualTo(9.5f));
    }

    [Test]
    public void GeneratedExtension_Multiply_IsVectorizedOrExact()
    {
        var values = CreateSpeeds(64);
        values.AsSpan().Multiply(3f, values.AsSpan());
        Assert.That(values[63].Value, Is.EqualTo(189f));
    }

    [Test]
    public void GeneratedExtension_MaxAndMin_AreAvailable()
    {
        var left = CreateSpeeds(8);
        var right = new SpeedBox[8];
        for (var i = 0; i < right.Length; i++)
        {
            right[i].Value = 8 - i;
        }

        var max = new SpeedBox[8];
        var min = new SpeedBox[8];
        left.AsSpan().Max(right.AsSpan(), max.AsSpan());
        left.AsSpan().Min(right.AsSpan(), min.AsSpan());

        // left = 0..7, right = 8..1
        Assert.That(max[0].Value, Is.EqualTo(8f));
        Assert.That(max[7].Value, Is.EqualTo(7f));
        Assert.That(min[0].Value, Is.EqualTo(0f));
        Assert.That(min[7].Value, Is.EqualTo(1f));
    }

    [Test]
    public void GeneratedExtension_GetMax_ReturnsComponent()
    {
        var values = CreateSpeeds(32);
        var max = values.AsSpan().GetMaxAsComponent();
        Assert.That(max.Value, Is.EqualTo(31f));
    }

    [Test]
    public void RenamedExtension_IsGenerated()
    {
        var values = new[] { new ScoreBox { Value = 1 }, new ScoreBox { Value = 2 } };
        values.AsSpan().AddValue(new ScoreBox { Value = 5 }, values.AsSpan());
        Assert.That(values[0].Value, Is.EqualTo(6));
        Assert.That(values[1].Value, Is.EqualTo(7));
    }

    [Test]
    public void GeneratedExtension_RespectsExplicitMode()
    {
        var values = CreateSpeeds(1024);

        // Serial path must produce the same values as the resolved default.
        values.AsSpan().Add(1f, values.AsSpan(), IterationMode.Serial);
        Assert.That(values[0].Value, Is.EqualTo(1f));
        Assert.That(values[1023].Value, Is.EqualTo(1024f));
    }

    // ------------------------------------------------------------------
    // Components<T> 层：与 ComponentsParallelExtensions 同形的 chunk 级扩展
    // ------------------------------------------------------------------

    private static float SumSpeed(EntityRepository repository, ComponentFilter filter)
    {
        using var chunks = repository.Search(filter);
        using var components = chunks.GetComponents<SpeedBox>();
        var segments = components.Segments;
        var sum = 0f;
        for (var i = 0; i < segments.Count; i++)
        {
            var span = segments[i];
            for (var j = 0; j < span.Length; j++) sum += span[j].Value;
        }

        return sum;
    }

    private static EntityRepository CreateSpeedRepository(int count)
    {
        var repository = new EntityRepository(TestAllocator.Shared);
        for (var i = 0; i < count; i++)
        {
            repository.Insert(new SpeedBox { Value = i });
        }

        return repository;
    }

    [Test]
    public void ComponentsExtension_AddWithComponentOperand_UpdatesAllChunks()
    {
        const int count = 5000;
        using var repository = CreateSpeedRepository(count);
        var filter = new ComponentFilter().Include<SpeedBox>();
        using var chunks = repository.Search(filter);
        using var components = chunks.GetComponents<SpeedBox>();
        components.Add(IterationMode.Simd, new SpeedBox { Value = 10f });
        Assert.That(components.Elements.Count, Is.EqualTo(count));
        Assert.That(SumSpeed(repository, filter), Is.EqualTo(count * (count - 1) / 2f + count * 10f));
    }

    [Test]
    public void ComponentsExtension_AddWithScalarOperand_IsGenerated()
    {
        const int count = 1000;
        using var repository = CreateSpeedRepository(count);
        var filter = new ComponentFilter().Include<SpeedBox>();
        using var chunks = repository.Search(filter);
        using var components = chunks.GetComponents<SpeedBox>();
        components.Add(IterationMode.Simd, 2.5f);
        Assert.That(SumSpeed(repository, filter), Is.EqualTo(count * (count - 1) / 2f + count * 2.5f));
    }

    [Test]
    public void ComponentsExtension_ParallelAndSerial_Agree()
    {
        const int count = 20000;
        var filter = new ComponentFilter().Include<SpeedBox>();

        using var serialRepository = CreateSpeedRepository(count);
        using (var chunks = serialRepository.Search(filter))
        using (var components = chunks.GetComponents<SpeedBox>())
        {
            components.Add(IterationMode.Simd, 1.5f);
        }

        using var parallelRepository = CreateSpeedRepository(count);
        using (var chunks = parallelRepository.Search(filter))
        using (var components = chunks.GetComponents<SpeedBox>())
        {
            components.Add(IterationMode.Simd | IterationMode.Parallel, 1.5f);
        }

        Assert.That(SumSpeed(parallelRepository, filter), Is.EqualTo(SumSpeed(serialRepository, filter)));
    }

    [Test]
    public void ComponentsExtension_SerialKernelMask_AlsoWorks()
    {
        const int count = 500;
        using var repository = CreateSpeedRepository(count);
        var filter = new ComponentFilter().Include<SpeedBox>();
        using var chunks = repository.Search(filter);
        using var components = chunks.GetComponents<SpeedBox>();
        components.Add(IterationMode.Serial, 3f);
        Assert.That(SumSpeed(repository, filter), Is.EqualTo(count * (count - 1) / 2f + count * 3f));
    }

    // ------------------------------------------------------------------
    // SpanTo：布局等价（无成员），可声明 lane 映射（"Field:Lane"，物理顺序必须一致）
    // ------------------------------------------------------------------

    /// <summary>四个 float 与 Vector4 布局等价。</summary>
    [SpanTo(typeof(ISpanVectorOperation<Vector4>))]
    public partial struct Quat
    {
        public float X;
        public float Y;
        public float Z;
        public float W;
    }

    /// <summary>两个 float 与 Vector2 布局等价，并显式声明 lane 映射 Y→X、Z→Y。</summary>
    [SpanTo(typeof(ISpanVectorOperation<Vector2>), Lane = new[] { "Y:X", "Z:Y" })]
    public partial struct YZ
    {
        public float Y;
        public float Z;
    }

    [Test]
    public void SpanTo_LayoutBridge_NormalizeTouchesEveryField()
    {
        var values = new Quat[4];
        values[0] = new Quat { X = 3f, Y = 4f, Z = 0f, W = 0f };
        values.AsSpan().Normalize(values.AsSpan());
        Assert.That(values[0].X, Is.EqualTo(0.6f).Within(1e-5f));
        Assert.That(values[0].Y, Is.EqualTo(0.8f).Within(1e-5f));
        Assert.That(values[0].Z, Is.EqualTo(0f).Within(1e-5f));
        Assert.That(values[0].W, Is.EqualTo(0f).Within(1e-5f));
    }

    [Test]
    public void SpanTo_LayoutBridge_ProjectionToFloatSpan()
    {
        var values = new Quat[4];
        values[0] = new Quat { X = 3f, Y = 4f };
        var lengths = new float[4];
        values.AsSpan().Length(lengths);
        Assert.That(lengths[0], Is.EqualTo(5f).Within(1e-5f));
    }

    [Test]
    public void SpanTo_LaneMapping_IsHonouredByTheKernel()
    {
        var values = new YZ[2];
        values[0] = new YZ { Y = 3f, Z = 4f };
        var lengths = new float[2];
        values.AsSpan().Length(lengths);
        Assert.That(lengths[0], Is.EqualTo(5f).Within(1e-5f));
    }

    /// <summary>单 float 组件，用 SpanTo 走布局桥接（operand 需要 SpanBridge.AsValue）。</summary>
    [SpanTo(typeof(ISpanNumberOperation<float>))]
    public partial struct Solo
    {
        public float Value;
    }

    [Test]
    public void SpanTo_ComponentOperand_IsBridgedFromLayout()
    {
        var values = new Solo[4];
        values[1].Value = 1f;
        var operand = new Solo { Value = 10f };
        var result = new Solo[4];
        values.AsSpan().Add(operand, result);
        Assert.That(result[0].Value, Is.EqualTo(10f));
        Assert.That(result[1].Value, Is.EqualTo(11f));
        Assert.That(result[3].Value, Is.EqualTo(10f));
    }

    /// <summary>私有字段：SpanTo 只需布局等价，不需要成员可见性。</summary>
    [SpanTo(typeof(ISpanNumberOperation<float>))]
    public partial record struct PrivateBox
    {
        private float Value;

        public void Set(float value) => Value = value;

        public float Get() => Value;
    }

    [Test]
    public void SpanTo_WorksWithPrivateField()
    {
        var values = new[] { new PrivateBox(), new PrivateBox() };
        values[0].Set(1f);
        values[1].Set(2f);

        values.AsSpan().Add(10f, values.AsSpan());

        Assert.That(values[0].Get(), Is.EqualTo(11f));
        Assert.That(values[1].Get(), Is.EqualTo(12f));
    }
}